#include <bits/stdc++.h>
using namespace std;

void applyOp(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [suffix middle prefix]
    vector<int> res;
    for (int i = n - y; i < n; i++) res.push_back(p[i]);
    for (int i = x; i < n - y; i++) res.push_back(p[i]);
    for (int i = 0; i < x; i++) res.push_back(p[i]);
    p = res;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int i = 0; i < n - 2; i++) {
        int j = -1;
        for (int k = i; k < n; k++) if (p[k] == i + 1) { j = k; break; }
        if (j == i) continue;

        // Need to get p[j] = i+1 to position i
        // If j is not at end (n-1), first move it to position 0
        if (j > 0 && j < n - 1) {
            int x = j, y = n - 1 - j;
            // suffix = p[n-y..n-1] = p[j+1..n-1], middle = p[j..j] = {p[j]}, prefix = p[0..j-1]
            // result: [p[j+1..n-1], p[j], p[0..j-1]]
            // Actually: x=j, y=n-1-j. x+y = n-1 < n. Good.
            ops.push_back({x, y});
            applyOp(p, x, y);
            j = n - 1 - j; // p[j] is now at position n-1-j... no, let me just find it
            for (int k = 0; k < n; k++) if (p[k] == i+1) { j = k; break; }
        }
        if (j == i) continue;
        // Now j is either 0 or n-1
        if (j == n - 1 && i + 1 <= n - 2) {
            // x = i+1, y = 1, need i+1+1 < n => i+2 < n => i < n-2 (guaranteed by loop)
            ops.push_back({i + 1, 1});
            applyOp(p, i + 1, 1);
        } else if (j == 0 && i > 0) {
            // x=1, y=n-1-i, need 1+n-1-i < n => n-i < n => i > 0
            ops.push_back({1, n - 1 - i});
            applyOp(p, 1, n - 1 - i);
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [a, b] : ops) printf("%d %d\n", a, b);
}
